struct Counter { long value; };
Counter counters[64];

void work(int tid) {
    for (int i = 0; i < 1000000; ++i)
        counters[tid].value++;   // 每线程只写自己的元素
}
// 主线程对 counters[0..N) 各起一个线程并发跑 work(tid)

void scale(float* a, const float* b, float k, int n) {
    for (int i = 0; i < n; ++i)
        a[i] = b[i] * k;
}
